package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;import java.util.*;
public final class Stage40Instrumentation extends Instrumentation{
 void check(boolean b,String why){if(!b)throw new AssertionError(why);}void note(String text){Bundle b=new Bundle();b.putString("stream",text+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 BananaEngine.Result ask(Context c,Semilla m,String s)throws Exception{return BananaEngine.run(c,s,new ArrayList<String[]>(),"",true,m);}
 @Override public void onStart(){Bundle b=new Bundle();try{Context c=getTargetContext();c.getSharedPreferences("banana-mobile-core",0).edit().clear().commit();Semilla m=OwnBrain.load(c);BananaEngine.Result out=ask(c,m,"que es un algoritmo");check(out.mode.equals("conocimiento_local")&&out.text.contains("instrucciones")&&out.text.contains("no consulté Internet"),"own model loads and answers offline on Android");out=ask(c,m,"dame un ejemplo");check(out.text.contains("ordenar tres números"),"local lesson followup");out=ask(c,m,"explicalo paso a paso");check(out.text.contains("1. Definí"),"step explanation");note("NATIVE_OWN_TOPIC_MODEL_AND_OFFLINE_FOLLOWUPS_OK");
  out=ask(c,m,"planea: crea a Tony una banana detective; agrega un pepino llamado Milo; Tony baila; Milo entra por la derecha; Tony dice \"Hola; vamos.\"");check(out.text.contains("5 pasos"),"persistent plan");out=ask(c,m,"aplica el plan");check(out.changed&&out.scene.cast.size()==2&&out.scene.dialogue.size()==1&&out.scene.dialogue.get(0).text.contains("Hola;"),"five-step real plan with dialogue");out=ask(c,m,"no, el que entra tiene que ser azul");check(out.changed&&out.scene.get("pepino").look.contains("azul"),"resolve correction to last entrant");String before=SceneStore.load(c).json().toString();out=ask(c,m,"primero pone a Tony rojo despues hace que un dragon vuele");check(!out.changed&&before.equals(SceneStore.load(c).json().toString()),"failed second step cannot commit first");ask(c,m,"corrige paso 2: continua con Milo saluda");out=ask(c,m,"aplica el plan");check(out.changed&&out.scene.get("banana").look.contains("rojo"),"repair and atomic commit");note("NATIVE_PLANS_ROLE_REPAIR_AND_ATOMICITY_OK");
  ask(c,m,"cuando diga \"fiesta verde\" quiero decir \"pone a Tony verde\"");out=ask(c,m,"fiesta verde");check(out.changed&&out.scene.get("banana").look.contains("verde"),"learned local user phrase");out=ask(c,m,"que entendiste");check(out.text.contains("fiesta verde")&&out.text.contains("pone a Tony verde"),"grounded explanation");ask(c,m,"anota esta correccion: no era ese personaje");check(ask(c,m,"mis correcciones").text.contains("no era ese personaje"),"user correction separate from weights");ask(c,m,"modo breve");check(!ask(c,m,"que es una variable").text.contains("Ejemplo:"),"saved answer style");note("NATIVE_TAUGHT_PHRASES_FEEDBACK_AND_STYLE_OK");b.putString("stream","PASS STAGE40 native Android own model loading, local lessons, followups, style, quote-aware plans, role correction, atomic failure/repair, learned user phrase and trace. No PC or external model used for inference.\n");finish(Activity.RESULT_OK,b);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));b.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,b);}}
}
